Настройка = кфк_т_ТестовыеДанные.СсылкаКонсьюмераОбщий();
ИмяСтатуса = "Обработано";
Для НомерЗаписи = 1 По 3 Цикл
Запись = РегистрыСведений.кфкВходящиеСообщения.СоздатьМенеджерЗаписи();
Запись.КлючЗаписи = ?(НомерЗаписи = 3, "VA-807c5b92-7a62-4c82-aa30-e1d2ab844299-3", "VA-807c5b92-7a62-4c82-aa30-e1d2ab844299");
Запись.МеткаЗагрузки = Число(?(НомерЗаписи = 2, "28119524081000000000500000010", "28119524080000000000500000009"));
Запись.МеткаИзменения = Запись.МеткаЗагрузки;
Запись.Статус = Перечисления.кфкСтатусыСообщений[ИмяСтатуса];
Запись.Консьюмер = Настройка;
Запись.КлючСообщения = "VA-807c5b92-7a62-4c82-aa30-e1d2ab844299-" + Формат(НомерЗаписи, "ЧГ=0");
Запись.КоличествоОбработок = 3;
Запись.ДатаОбработки = Дата(2026, 1, 1, 10, 0, 2);
Запись.ДлОбработкиМС = 125;
Запись.Топик = "1c.test-catalogs";
Запись.Раздел = 2;
Запись.Смещение = 40 + НомерЗаписи;
Запись.ДатаЗаписи = Дата(2026, 1, 1, 10, 0, 0);
Запись.ДатаЗагрузки = Дата(2026, 1, 1, 10, 0, 1);
Заголовки = Новый Соответствие;
Заголовки.Вставить("va-marker", Запись.КлючСообщения);
Запись.Заголовки = кфкОбщегоНазначенияСлужебный.ЗначениеВХранилище(Заголовки);
Запись.ТелоСообщения = кфкОбщегоНазначенияСлужебный.ЗначениеВХранилище(
"{""marker"":""" + Запись.КлючСообщения + """}");
Запись.ТекстЖурнала = "VA: исходный журнал";
Запись.Записать();
КонецЦикла;

Снимок = ХранилищеОбщихНастроек.Загрузить("VA.ПанельАдминистрирования", "VA-Панель-b0a66266-0194-4e63-b7d0-b76f888addc9",, "АдминистраторТакси");
Если Снимок = Неопределено Тогда
ВызватьИсключение "Снимок настроек не найден; подготовка остановлена.";
КонецЕсли;
Задания = РегламентныеЗаданияСервер.НайтиЗадания(
Новый Структура("УникальныйИдентификатор", Снимок.ИдентификаторЗадания));
Если Задания.Количество() <> 1 Тогда
ВызватьИсключение "Исходное задание не найдено однозначно; снимок оставлен для восстановления.";
КонецЕсли;
Задание = Задания[0];
Задание.Использование = Ложь;
Задание.Записать();
Расписание = ОбщегоНазначенияКлиентСервер.СтруктураВРасписание(Неопределено);
Расписание.ДатаНачала = НачалоДня(ДобавитьМесяц(ТекущаяДатаСеанса(), 1));
Расписание.ДатаКонца = Расписание.ДатаНачала;
Расписание.ПериодПовтораДней = 1;
Задание.Расписание = Расписание;
Задание.Записать();
Константы.кфкБлокировкаИнтеграции.Установить(Истина);
Константы.кфкИспользоватьИнтеграцию.Установить(Истина);

Если РегламентныеЗаданияСервер.РаботаСВнешнимиРесурсамиЗаблокирована() Тогда
РегламентныеЗаданияСервер.РазблокироватьРаботуСВнешнимиРесурсами();
// БСП может включить задание из списка отключённых. Включение выполняет сценарий.
Снимок = ХранилищеОбщихНастроек.Загрузить("VA.ПанельАдминистрирования", "VA-Панель-b0a66266-0194-4e63-b7d0-b76f888addc9",, "АдминистраторТакси");
РегламентныеЗаданияСервер.ИзменитьЗадание(Снимок.ИдентификаторЗадания,
Новый Структура("Использование", Ложь));
КонецЕсли;

Снимок = ХранилищеОбщихНастроек.Загрузить("VA.ПанельАдминистрирования", "VA-Панель-b0a66266-0194-4e63-b7d0-b76f888addc9",, "АдминистраторТакси");
Если Снимок = Неопределено Тогда
ВызватьИсключение "Снимок настроек не найден; остановка задания отменена.";
КонецЕсли;
Задания = РегламентныеЗаданияСервер.НайтиЗадания(
Новый Структура("УникальныйИдентификатор", Снимок.ИдентификаторЗадания));
Если Задания.Количество() <> 1 Тогда
ВызватьИсключение "Исходное задание не найдено; снимок оставлен для восстановления.";
КонецЕсли;
Задание = Задания[0];
Константы.кфкБлокировкаИнтеграции.Установить(Истина);
Задание.Использование = Ложь;
Задание.Записать();
ОтборАктивных = Новый Структура("ИмяМетода,Состояние",
Задание.Метаданные.ИмяМетода, СостояниеФоновогоЗадания.Активно);
Для Каждого ФоновоеЗадание Из ФоновыеЗадания.ПолучитьФоновыеЗадания(ОтборАктивных) Цикл
Если ФоновоеЗадание.РегламентноеЗадание = Неопределено
Или ФоновоеЗадание.РегламентноеЗадание.УникальныйИдентификатор <> Снимок.ИдентификаторЗадания Тогда
ВызватьИсключение "Обнаружено чужое выполнение; снимок оставлен для восстановления.";
КонецЕсли;
ЗавершённоеЗадание = ФоновоеЗадание.ОжидатьЗавершенияВыполнения(30);
Если ЗавершённоеЗадание.Состояние = СостояниеФоновогоЗадания.Активно Тогда
ВызватьИсключение "Задание ещё выполняется; блокировка и снимок сохранены.";
КонецЕсли;
КонецЦикла;
// Отключение расписания не останавливает потоки, запущенные заданием.
ЛимитОжиданияПотоковВСекундах = 30;
МоментОкончанияОжидания = ТекущаяУниверсальнаяДата() + ЛимитОжиданияПотоковВСекундах;
Потоки = кфкФоновыеОперацииСлужебный.ПолучитьПотоки(СостояниеФоновогоЗадания.Активно);
Пока Потоки.Количество() > 0 Цикл
ОсталосьСекунд = МоментОкончанияОжидания - ТекущаяУниверсальнаяДата();
Если ОсталосьСекунд <= 0 Тогда
ВызватьИсключение "Фоновые потоки Kafka не завершились; блокировка и снимок сохранены.";
КонецЕсли;
ФоновыеЗадания.ОжидатьЗавершенияВыполнения(Потоки, ОсталосьСекунд);
Потоки = кфкФоновыеОперацииСлужебный.ПолучитьПотоки(СостояниеФоновогоЗадания.Активно);
КонецЦикла;

Идентификатор = Новый УникальныйИдентификатор("807c5b92-7a62-4c82-aa30-e1d2ab844299");
БазовыйКлюч = "VA-" + Строка(Идентификатор);
Ключ = "VA-807c5b92-7a62-4c82-aa30-e1d2ab844299";
Если "кфкВходящиеСообщения" = "кфкИсходящиеСообщения" Тогда
Менеджер = РегистрыСведений.кфкИсходящиеСообщения;
Если Ключ <> БазовыйКлюч Тогда
Ссылка = Справочники.кфк_т_ТестовыйСправочник.ПолучитьСсылку(Идентификатор);
КлючиОбъекта = кфкОбработкаСобытийСлужебный.КлючЗаписиИсходящихСообщений(Ссылка);
Если КлючиОбъекта = Неопределено Или КлючиОбъекта.Найти(Ключ) = Неопределено Тогда
ВызватьИсключение "Ключ исходящих сообщений не принадлежит тестовому объекту.";
КонецЕсли;
КонецЕсли;
ИначеЕсли "кфкВходящиеСообщения" = "кфкВходящиеСообщения" Тогда
Менеджер = РегистрыСведений.кфкВходящиеСообщения;
Если Ключ <> БазовыйКлюч Тогда
ВызватьИсключение "Ключ входящих сообщений не принадлежит тестовому объекту.";
КонецЕсли;
Иначе
ВызватьИсключение "Неизвестный регистр сообщений.";
КонецЕсли;
Для Каждого ТекущийКлюч Из СтрРазделить(Ключ + "," + БазовыйКлюч + "-3", ",") Цикл
Сообщения = кфкОбщегоНазначенияСлужебный.СоздатьНаборЗаписей(Менеджер);
Сообщения.Отбор.КлючЗаписи.Установить(ТекущийКлюч);
Сообщения.Записать();
Очередь = кфкОбщегоНазначенияСлужебный.СоздатьНаборЗаписей(РегистрыСведений.кфкОчередьПотоков);
Очередь.Отбор.Ключ.Установить(ТекущийКлюч);
Очередь.Записать();
КонецЦикла;

Снимок = ХранилищеОбщихНастроек.Загрузить("VA.ПанельАдминистрирования", "VA-Панель-b0a66266-0194-4e63-b7d0-b76f888addc9",, "АдминистраторТакси");
Если Снимок = Неопределено Тогда
ВызватьИсключение "Снимок настроек не найден; восстановление остановлено.";
КонецЕсли;
Задания = РегламентныеЗаданияСервер.НайтиЗадания(
Новый Структура("УникальныйИдентификатор", Снимок.ИдентификаторЗадания));
Если Задания.Количество() <> 1 Тогда
ВызватьИсключение "Исходное задание не найдено однозначно; снимок оставлен для восстановления.";
КонецЕсли;
Задание = Задания[0];
Если Задание = Неопределено Тогда
ВызватьИсключение "Исходное регламентное задание исчезло; снимок оставлен для восстановления.";
КонецЕсли;
Задание.Использование = Ложь;
Задание.Записать();
Для Каждого Регистр Из Снимок.Регистры Цикл
Набор = РегистрыСведений[Регистр.Ключ].СоздатьНаборЗаписей();
Набор.Загрузить(Регистр.Значение);
Набор.Записать();
Набор.Прочитать();
Если Не ЮТСравнениеСлужебныйКлиентСервер.ЗначенияРавны(Набор.Выгрузить(), Регистр.Значение) Тогда
ВызватьИсключение "Не восстановлен регистр " + Регистр.Ключ;
КонецЕсли;
КонецЦикла;
Для Каждого Настройка Из Снимок.Константы Цикл
Константы[Настройка.Ключ].Установить(Настройка.Значение);
Если Константы[Настройка.Ключ].Получить() <> Настройка.Значение Тогда
ВызватьИсключение "Не восстановлена константа " + Настройка.Ключ;
КонецЕсли;
КонецЦикла;
Для Каждого Свойство Из Снимок.Задание Цикл
Если Свойство.Ключ <> "Использование" Тогда
Задание[Свойство.Ключ] = ?(Свойство.Ключ = "Расписание",
ОбщегоНазначенияКлиентСервер.СтруктураВРасписание(Свойство.Значение), Свойство.Значение);
КонецЕсли;
КонецЦикла;
Задание.Использование = Снимок.Задание.Использование;
Задание.Записать();
Задания = РегламентныеЗаданияСервер.НайтиЗадания(
Новый Структура("УникальныйИдентификатор", Снимок.ИдентификаторЗадания));
Если Задания.Количество() <> 1 Тогда
ВызватьИсключение "Исходное задание не найдено однозначно; снимок оставлен для восстановления.";
КонецЕсли;
Задание = Задания[0];
Для Каждого Свойство Из Снимок.Задание Цикл
Проверка = ?(Свойство.Ключ = "Расписание",
ОбщегоНазначенияКлиентСервер.РасписаниеВСтруктуру(Задание.Расписание), Задание[Свойство.Ключ]);
Если Не ЮТСравнениеСлужебныйКлиентСервер.ЗначенияРавны(Проверка, Свойство.Значение) Тогда
ВызватьИсключение "Не восстановлено свойство задания " + Свойство.Ключ;
КонецЕсли;
КонецЦикла;
// Снимок сохраняется после проверки для аудита и восстановления после аварии.

Метки = СтрРазделить(Ванесса.Объект.ЗначениеНаСервере, "|");
Контекст.Вставить("МеткаЗаписи", Метки[0]);
Контекст.Вставить("МеткаВторая", Метки[1]);
Контекст.Вставить("МеткаЗаписиВФорме", Формат(Число(Метки[0]), "ЧГ=3,0;ЧДЦ=0"));
Контекст.Вставить("МеткаВтораяВФорме", Формат(Число(Метки[1]), "ЧГ=3,0;ЧДЦ=0"));

Если кфкФоновыеОперацииСлужебный.ПолучитьПотоки(СостояниеФоновогоЗадания.Активно).Количество() > 0 Тогда
ВызватьИсключение "Перед проверкой настроек должны завершиться активные потоки Kafka.";
КонецЕсли;
Задания = РегламентныеЗадания.ПолучитьРегламентныеЗадания(
Новый Структура("Метаданные", Метаданные.РегламентныеЗадания.кфкЗапускИнтеграции));
Если Задания.Количество() <> 1 Тогда
ВызватьИсключение "Нужно одно заранее созданное регламентное задание Kafka.";
КонецЕсли;
Задание = Задания[0];
Отбор = Новый Структура("ИмяМетода,Состояние", Задание.Метаданные.ИмяМетода, СостояниеФоновогоЗадания.Активно);
Если ФоновыеЗадания.ПолучитьФоновыеЗадания(Отбор).Количество() > 0 Тогда
ВызватьИсключение "Перед проверкой должно завершиться регламентное задание Kafka.";
КонецЕсли;
Если Задание.Использование
И (Не Константы.кфкБлокировкаИнтеграции.Получить() Или Не ПолучитьФункциональнуюОпцию("кфкБлокировкаИнтеграции"))
И Задание.Расписание.ДатаНачала <= КонецДня(ТекущаяДата()) Тогда
ВызватьИсключение "Остановите фоновый обмен или установите безопасное будущее расписание Kafka.";
КонецЕсли;
Снимок = Новый Структура;
Снимок.Вставить("ИдентификаторЗадания", Задание.УникальныйИдентификатор);
Снимок.Вставить("Константы", Новый Структура);
Снимок.Вставить("Регистры", Новый Структура);
Снимок.Вставить("Задание", Новый Структура);
Снимок.Константы.Вставить("кфкИспользоватьИнтеграцию", Константы.кфкИспользоватьИнтеграцию.Получить());
Снимок.Константы.Вставить("кфкБлокировкаИнтеграции", Константы.кфкБлокировкаИнтеграции.Получить());
РазделПанели = "Основное";
Если РазделПанели = "Логирование" Тогда
Снимок.Константы.Вставить("кфкКаталогЛогированияКомпоненты", Константы.кфкКаталогЛогированияКомпоненты.Получить());
Снимок.Константы.Вставить("кфкФорматИмениФайловЛогированияКомпоненты", Константы.кфкФорматИмениФайловЛогированияКомпоненты.Получить());
Набор = РегистрыСведений.кфкПараметрыЛогирования.СоздатьНаборЗаписей();
Набор.Прочитать();
Снимок.Регистры.Вставить("кфкПараметрыЛогирования", Набор.Выгрузить());
ИначеЕсли РазделПанели = "Очереди" Тогда
Снимок.Константы.Вставить("кфкИспользоватьКонтрольИнтеграции", Константы.кфкИспользоватьКонтрольИнтеграции.Получить());
Для Каждого ИмяРегистра Из СтрРазделить("кфкПараметрыОчисткиХранилища,кфкПараметрыКонтроляИнтеграции", ",") Цикл
Набор = РегистрыСведений[ИмяРегистра].СоздатьНаборЗаписей();
Набор.Прочитать();
Снимок.Регистры.Вставить(ИмяРегистра, Набор.Выгрузить());
КонецЦикла;
ИначеЕсли РазделПанели = "РегламентноеЗадание" Тогда
Снимок.Задание.Вставить("Наименование", Задание.Наименование);
Снимок.Задание.Вставить("ИмяПользователя", Задание.ИмяПользователя);
Снимок.Задание.Вставить("КоличествоПовторовПриАварийномЗавершении", Задание.КоличествоПовторовПриАварийномЗавершении);
Снимок.Задание.Вставить("ИнтервалПовтораПриАварийномЗавершении", Задание.ИнтервалПовтораПриАварийномЗавершении);
ИначеЕсли РазделПанели = "ФоновыеЗадания" Тогда
Снимок.Константы.Вставить("кфкИспользоватьПотоковыйРежим", Константы.кфкИспользоватьПотоковыйРежим.Получить());
ИначеЕсли РазделПанели <> "Основное" Тогда
ВызватьИсключение "Неизвестный раздел панели для снимка: " + РазделПанели;
КонецЕсли;
Снимок.Задание.Вставить("Использование", Задание.Использование);
Снимок.Задание.Вставить("Расписание", ОбщегоНазначенияКлиентСервер.РасписаниеВСтруктуру(Задание.Расписание));
КлючСнимка = "VA-Панель-" + Строка(Новый УникальныйИдентификатор);
ХранилищеОбщихНастроек.Сохранить("VA.ПанельАдминистрирования", КлючСнимка, Снимок,, "АдминистраторТакси");
ПроверкаСнимка = ХранилищеОбщихНастроек.Загрузить("VA.ПанельАдминистрирования", КлючСнимка,, "АдминистраторТакси");
Если Не ЮТСравнениеСлужебныйКлиентСервер.ЗначенияРавны(ПроверкаСнимка, Снимок) Тогда
ВызватьИсключение "Не подтверждена запись снимка; подготовка остановлена.";
КонецЕсли;
Объект.ЗначениеНаСервере = КлючСнимка;
